const ok = nsIPrompt_promptUsernameAndPassword(
  aDialogTitle,
  aText,
  aUsername,
  aPassword,
  checkBoxLabel,
  checkBox
);

if (!ok || !checkBox.value || !origin) {
  return ok;
}

if (!lazy.enforcePrimaryPassword()) {
  return ok;
}

const newLogin = new LoginInfo(
  origin,
  null,
  realm,
  aUsername.value,
  aPassword.value
);
await Services.logins.addLoginAsync(newLogin);

return ok;
